from typing import Literal

import reflex as rx
from reflex.components.component import ComponentNamespace

from .core import cn

LiteralOrientation = Literal["horizontal", "vertical"]


class ClassNames:
    ROOT = "group/timeline flex data-[orientation=horizontal]:w-full data-[orientation=horizontal]:flex-row data-[orientation=vertical]:flex-col"
    ITEM = "group/timeline-item relative flex flex-1 flex-col gap-0.5 group-data-[orientation=vertical]/timeline:ms-8 group-data-[orientation=horizontal]/timeline:mt-8 group-data-[orientation=horizontal]/timeline:not-last:pe-8 group-data-[orientation=vertical]/timeline:not-last:pb-6 has-[+[data-completed]]:**:data-[slot=timeline-separator]:bg-primary"
    HEADER = ""
    TITLE = "font-medium text-sm"
    CONTENT = "text-muted-foreground text-sm"
    DATE = "mb-1 block font-medium text-muted-foreground text-xs group-data-[orientation=vertical]/timeline:max-sm:h-4"
    INDICATOR = "group-data-[orientation=horizontal]/timeline:-top-6 group-data-[orientation=horizontal]/timeline:-translate-y-1/2 group-data-[orientation=vertical]/timeline:-left-6 group-data-[orientation=vertical]/timeline:-translate-x-1/2 absolute size-4 rounded-full border-2 border-primary/20 group-data-[orientation=vertical]/timeline:top-0 group-data-[orientation=horizontal]/timeline:left-0 group-data-completed/timeline-item:border-primary"
    SEPARATOR = "group-data-[orientation=horizontal]/timeline:-top-6 group-data-[orientation=horizontal]/timeline:-translate-y-1/2 group-data-[orientation=vertical]/timeline:-left-6 group-data-[orientation=vertical]/timeline:-translate-x-1/2 absolute self-start bg-primary/10 group-last/timeline-item:hidden group-data-[orientation=horizontal]/timeline:h-0.5 group-data-[orientation=vertical]/timeline:h-[calc(100%-1rem-0.25rem)] group-data-[orientation=horizontal]/timeline:w-[calc(100%-1rem-0.25rem)] group-data-[orientation=vertical]/timeline:w-0.5 group-data-[orientation=horizontal]/timeline:translate-x-4.5 group-data-[orientation=vertical]/timeline:translate-y-4.5"


def timeline_root(
    *children,
    orientation: LiteralOrientation = "vertical",
    class_name: str = "",
    **props,
) -> rx.Component:
    return rx.el.div(
        *children,
        class_name=cn(ClassNames.ROOT, class_name),
        data_slot="timeline",
        data_orientation=orientation,
        **props,
    )


def timeline_item(
    *children,
    step: int,
    active_step: int,
    class_name: str = "",
    **props,
) -> rx.Component:
    completed = step <= active_step

    return rx.el.div(
        *children,
        class_name=cn(ClassNames.ITEM, class_name),
        data_slot="timeline-item",
        data_completed="" if completed else None,
        **props,
    )


def timeline_header(
    *children,
    class_name: str = "",
    **props,
) -> rx.Component:
    return rx.el.div(
        *children,
        class_name=cn(ClassNames.HEADER, class_name),
        data_slot="timeline-header",
        **props,
    )


def timeline_title(
    *children,
    class_name: str = "",
    **props,
) -> rx.Component:
    return rx.el.h3(
        *children,
        class_name=cn(ClassNames.TITLE, class_name),
        data_slot="timeline-title",
        **props,
    )


def timeline_content(
    *children,
    class_name: str = "",
    **props,
) -> rx.Component:
    return rx.el.div(
        *children,
        class_name=cn(ClassNames.CONTENT, class_name),
        data_slot="timeline-content",
        **props,
    )


def timeline_date(
    *children,
    class_name: str = "",
    **props,
) -> rx.Component:
    return rx.el.time(
        *children,
        class_name=cn(ClassNames.DATE, class_name),
        data_slot="timeline-date",
        **props,
    )


def timeline_indicator(
    *children,
    class_name: str = "",
    **props,
) -> rx.Component:
    return rx.el.div(
        *children,
        class_name=cn(ClassNames.INDICATOR, class_name),
        data_slot="timeline-indicator",
        aria_hidden=True,
        **props,
    )


def timeline_separator(
    class_name: str = "",
    **props,
) -> rx.Component:
    return rx.el.div(
        class_name=cn(ClassNames.SEPARATOR, class_name),
        data_slot="timeline-separator",
        aria_hidden=True,
        **props,
    )

from typing import Any, Literal, Self, cast

import reflex as rx
from reflex.components.component import ComponentNamespace
from reflex.vars.base import Var
from reflex_components_core.el import Div

from .core import CoreComponent, cn

LiteralTrendDirection = Literal["up", "down", "neutral"]


class ClassNames:
    ROOT = "flex flex-col gap-y-2 p-4 rounded-lg border border-input bg-card shadow-sm"
    LABEL = "text-sm font-medium text-muted-foreground"
    VALUE = "text-3xl font-bold tracking-tight text-foreground"
    TREND_CONTAINER = "flex flex-row items-center gap-x-1.5"
    TREND_BADGE = "flex flex-row items-center gap-x-1 px-1.5 py-0.5 rounded-md text-[10px] font-bold uppercase tracking-wider"


class MetricRoot(CoreComponent, Div):
    @classmethod
    def create(cls, *children: Component, **props: Any) -> Self:
        cls.set_class_name(ClassNames.ROOT, props)
        return super().create(*children, **props)


class HighLevelMetric(MetricRoot):
    @classmethod
    def create(
        cls,
        label: Var[str] | str,
        value: Var[str] | str,
        trend: Var[str] | str | None = None,
        trend_direction: Var[LiteralTrendDirection] | LiteralTrendDirection = "neutral",
        **props,
    ) -> Self:

        trend_color = rx.match(
            trend_direction,
            ("up", "text-emerald-600 bg-emerald-500/10 dark:text-emerald-400"),
            ("down", "text-destructive bg-destructive/10"),
            "text-muted-foreground bg-secondary",
        )

        return cast(
            "Self",
            MetricRoot.create(
                rx.el.div(
                    rx.el.p(label, class_name=ClassNames.LABEL),
                    class_name="flex flex-row items-center justify-between w-full",
                ),
                rx.el.div(
                    rx.el.p(value, class_name=ClassNames.VALUE),
                    rx.cond(
                        trend,
                        rx.el.div(
                            rx.el.div(
                                rx.el.span(trend),
                                class_name=cn(
                                    ClassNames.TREND_BADGE,
                                    cast("Var[Any]", trend_color),
                                ),
                            ),
                            class_name=ClassNames.TREND_CONTAINER,
                        ),
                    ),
                    class_name="flex flex-row items-baseline justify-between w-full",
                ),
                **props,
            ),
        )


class MetricNamespace(ComponentNamespace):
    root = staticmethod(MetricRoot.create)
    __call__ = staticmethod(HighLevelMetric.create)


metric = MetricNamespace()

from typing import Any, Literal, Self

from reflex.components.component import ComponentNamespace
from reflex.vars.base import Var
from reflex_components_core.core.foreach import foreach
from reflex_components_core.el import (
    Caption,
    Div,
    Table,
    Tbody,
    Td,
    Tfoot,
    Th,
    Thead,
    Tr,
)

from .core import CoreComponent, cn

LiteralAlign = Literal["left", "center", "right"]


class ClassNames:
    ROOT = "w-full overflow-auto rounded-lg border border-input bg-card shadow-sm"
    TABLE = "w-full caption-bottom text-sm border-collapse"
    HEADER = "[&_tr]:border-b bg-secondary/50 backdrop-blur-sm sticky top-0"
    BODY = "[&_tr:last-child]:border-0"
    FOOTER = "border-t bg-muted/50 font-medium [&>tr]:last:border-b-0"
    ROW = "border-b transition-colors data-[state=selected]:bg-muted hover:bg-muted/50"
    HEAD = "h-10 px-4 text-left align-middle font-semibold text-muted-foreground [&:has([role=checkbox])]:pr-0 whitespace-nowrap"
    CELL = "p-4 align-middle [&:has([role=checkbox])]:pr-0"
    CAPTION = "mt-4 text-sm text-muted-foreground"


class TableRoot(CoreComponent, Div):
    @classmethod
    def create(cls, *children: Component, **props: Any) -> Self:

        cls.set_class_name(ClassNames.ROOT, props)

        table_props: dict[str, Any] = {
            "class_name": ClassNames.TABLE,
        }
        return super().create(Table.create(*children, **table_props), **props)


class TableHeader(CoreComponent, Thead):
    @classmethod
    def create(cls, *children: Component, **props: Any) -> Self:
        cls.set_class_name(ClassNames.HEADER, props)
        return super().create(*children, **props)


class TableBody(CoreComponent, Tbody):
    @classmethod
    def create(cls, *children: Component, **props: Any) -> Self:
        cls.set_class_name(ClassNames.BODY, props)
        return super().create(*children, **props)


class TableFooter(CoreComponent, Tfoot):
    @classmethod
    def create(cls, *children: Component, **props: Any) -> Self:
        cls.set_class_name(ClassNames.FOOTER, props)
        return super().create(*children, **props)


class TableRow(CoreComponent, Tr):
    @classmethod
    def create(cls, *children: Component, **props: Any) -> Self:
        cls.set_class_name(ClassNames.ROW, props)
        return super().create(*children, **props)


class TableHead(CoreComponent, Th):
    @classmethod
    def create(cls, *children: Component, **props: Any) -> Self:
        cls.set_class_name(ClassNames.HEAD, props)
        return super().create(*children, **props)


class TableCell(CoreComponent, Td):
    @classmethod
    def create(cls, *children: Component, **props: Any) -> Self:
        cls.set_class_name(ClassNames.CELL, props)
        return super().create(*children, **props)


class TableCaption(CoreComponent, Caption):
    @classmethod
    def create(cls, *children: Component, **props: Any) -> Self:
        cls.set_class_name(ClassNames.CAPTION, props)
        return super().create(*children, **props)


class HighLevelTable(TableRoot):
    @classmethod
    def create(
        cls,
        data: Var[list[dict[str, Any]]] | list[dict[str, Any]],
        columns: list[dict[str, Any]] | None = None,
        striped: bool = False,
        **props,
    ) -> Self:

        if columns is None and isinstance(data, list) and len(data) > 0:
            columns = [
                {"header": k.replace("_", " ").title(), "accessor": k} for k in data[0]
            ]
        elif columns is None:
            columns = []

        header_row = TableRow.create(
            *[
                TableHead.create(
                    col.get("header", ""),
                    class_name=cn(
                        "text-right" if col.get("align") == "right" else "",
                        "text-center" if col.get("align") == "center" else "",
                        col.get("class_name", ""),
                    ),
                )
                for col in columns
            ],
        )

        if isinstance(data, Var):
            body_content = foreach(
                data,
                lambda row: TableRow.create(
                    *[
                        TableCell.create(
                            row[col["accessor"]],
                            class_name=cn(
                                "text-right" if col.get("align") == "right" else "",
                                "text-center" if col.get("align") == "center" else "",
                                col.get("class_name", ""),
                            ),
                        )
                        for col in columns
                    ],
                    class_name=cn(
                        "even:bg-secondary/30" if striped else "",
                    ),
                ),
            )
        else:
            body_content = [
                TableRow.create(
                    *[
                        TableCell.create(
                            row.get(col["accessor"], ""),
                            class_name=cn(
                                "text-right" if col.get("align") == "right" else "",
                                "text-center" if col.get("align") == "center" else "",
                                col.get("class_name", ""),
                            ),
                        )
                        for col in columns
                    ],
                    class_name=cn(
                        "even:bg-secondary/30" if striped and i % 2 == 1 else "",
                    ),
                )
                for i, row in enumerate(data)
            ]

        return super().create(
            TableHeader.create(header_row),
            TableBody.create(
                body_content,
            ),
            **props,
        )


class TableNamespace(ComponentNamespace):
    root = staticmethod(TableRoot.create)
    header = staticmethod(TableHeader.create)
    body = staticmethod(TableBody.create)
    footer = staticmethod(TableFooter.create)
    row = staticmethod(TableRow.create)
    head = staticmethod(TableHead.create)
    cell = staticmethod(TableCell.create)
    caption = staticmethod(TableCaption.create)
    __call__ = staticmethod(HighLevelTable.create)


table = TableNamespace()

